public long huffmanCost(int[] freq) {
    if (freq.length == 1) {
        return freq[0]; // single symbol: 1-bit code by convention
    }
    List<Long> pool = new ArrayList<>();
    for (int f : freq) {
        pool.add((long) f);
    }
    long total = 0;
    while (pool.size() > 1) {
        int i1 = minIndex(pool, -1);
        int i2 = minIndex(pool, i1);
        long sum = pool.get(i1) + pool.get(i2);
        total += sum;
        pool.remove(Math.max(i1, i2));
        pool.remove(Math.min(i1, i2));
        pool.add(sum);
    }
    return total;
}

private int minIndex(List<Long> pool, int skip) {
    int best = -1;
    for (int i = 0; i < pool.size(); i++) {
        if (i == skip) {
            continue;
        }
        if (best == -1 || pool.get(i) < pool.get(best)) {
            best = i;
        }
    }
    return best;
}

public long huffmanCost(int[] freq) {
    if (freq.length == 1) {
        return freq[0];
    }
    PriorityQueue<Node> heap = new PriorityQueue<>((x, y) -> Long.compare(x.freq, y.freq));
    for (int f : freq) {
        heap.offer(new Node(f, null, null));
    }
    long total = 0;
    while (heap.size() > 1) {
        Node a = heap.poll();
        Node b = heap.poll();
        Node parent = new Node(a.freq + b.freq, a, b);
        total += parent.freq;
        heap.offer(parent);
    }
    return total; // heap.peek() is the root of the code tree
}

private static class Node {
    long freq;
    Node left, right;
    Node(long freq, Node left, Node right) {
        this.freq = freq;
        this.left = left;
        this.right = right;
    }
}
